<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { prepareCloud } from '../cloudPreparation'
import CloudBotAccess from '../components/CloudBotAccess.vue'
import CharacterCards from '../components/CharacterCards.vue'
import type { CharacterCard, CharacterSummary } from '@shared/characterCard'
import { AI_DEFAULTS, type AiSettingsView, type NumenCommand, type NumenSnapshot } from '@shared/numen'
import type { CommunityFile, ModInstallPlan } from '@shared/types'
import { numenApi } from '../numenApi'
import { communityFiles, prepareModInstall, commitModInstall, discardModInstall, errText } from '../api'
import { launcherInstances, canManageInstanceMods, resolveLauncherTarget, selectedLauncherInstance, isCloudInstance, displayVersionName, openCloudCenter, refreshInstalled, store, toast } from '../store'
const playerCommandBot=ref('')
const dormantChoice=ref('')
const invokeNumen=(method:string,...args:unknown[])=>window.kamucl.invoke('numen:'+method,...args)
const onlinePlayerRoster=computed(()=>((playerRoster.value.length?playerRoster.value:state.value.companions) as Array<{id:string;name:string;online?:boolean}>).filter(b=>b.online!==false))
const playerRoster=ref<Array<{id:string;name:string;online?:boolean}>>([])
async function refreshPlayerRoster(){playerRoster.value=isCloudInstance(selected.value)?(await window.kamucl.invoke('numen:cloudBotRoster') as any).roster:state.value.companions}
async function installCloudSupport(){
 const cloud=selected.value;if(!isCloudInstance(cloud))return
 await work('enable',async()=>{
  const installed=await invokeNumen('cloudInstallSupport') as {cancelled?:boolean};if(installed.cancelled)return
  const ref={instanceId:cloud.cloudInstanceId,saveId:cloud.cloudSaveId}
  if(!await prepareCloud(ref))return
  const result=await invokeNumen('cloudBotsBind',ref) as {snapshot:NumenSnapshot};accept(result.snapshot)
  toast('云端陪玩环境已发布、同步并启用','success')
 })
}
async function enableInstance(){
 if(isCloudInstance(selected.value)&&!state.value.enabled){await installCloudSupport();return}
 if(!state.value.installed){await chooseFiles();return}
 await work('enable',async()=>{accept(await window.kamucl.invoke('numen:instanceEnable',!state.value.enabled) as NumenSnapshot)})
}
const pageTab=ref<'runtime'|'characters'|'cloud'>('runtime')
const roleCards=ref<CharacterSummary[]>([])
const boundCard=ref<CharacterCard>()
const phaseLabels = { disconnected:'尚未连接', ready:'已连接 · 待启动', listening:'正在陪玩 · 等待消息', thinking:'正在思考', acting:'正在执行', stopped:'已停止', error:'需要处理' }
const state = ref<NumenSnapshot>({installed:false,mcpEnabled:false,quietFallback:false,endpoint:'http://127.0.0.1:8765/mcp',hasToken:false,connected:false,companions:[],tools:[],phase:'disconnected',logs:[],turns:0,inputTokens:0,outputTokens:0})
const form = reactive({...AI_DEFAULTS,apiKey:''})
const saved = ref<AiSettingsView>()
const busy = ref(''),error = ref(''),tab = ref<'companion'|'model'|'guide'>('companion'),choice = ref(''),message = ref(''),newName = ref('NomadBot')
const logFilter = ref('all'),autoScroll = ref(true),logEl = ref<HTMLElement>()
const files = ref<CommunityFile[]>([]),installOpen = ref(false),plan = ref<ModInstallPlan>(),planTarget = ref<{id:string;folder:string}>(),confirmWarnings = ref(false),pickedFile = ref('')
let unsubscribe: (()=>void)|undefined
let disposed=false
const options=computed(()=>launcherInstances.value.map(instance=>({key:JSON.stringify([instance.folder,instance.id]),instance})))
const selected=computed(()=>options.value.find(option=>option.key===choice.value)?.instance)
const localTarget=computed(()=>{const instance=resolveLauncherTarget(selected.value);return instance?{id:instance.id,folder:instance.folder||store.settings?.activeFolder||store.settings?.gameDir||''}:undefined})
const bound=computed(()=>!!localTarget.value&&state.value.target?.id===localTarget.value.id&&state.value.target?.folder===localTarget.value.folder)
const active=computed(()=>['listening','thinking','acting'].includes(state.value.phase))
const logEntries=computed(()=>state.value.logs.filter(log=>logFilter.value==='all'||log.kind===logFilter.value))
const statusTone=computed(()=>state.value.phase==='error'?'bad':active.value?'live':state.value.connected?'connected':'')
const commands:Array<{kind:NumenCommand;label:string;icon:string;direct?:boolean}>=[{kind:'status',label:'查看状态',icon:'◎',direct:true},{kind:'look',label:'观察周围',icon:'◉',direct:true},{kind:'inventory',label:'查看背包',icon:'▣',direct:true},{kind:'follow',label:'跟随我',icon:'↗'},{kind:'come',label:'到我身边',icon:'⌂'},{kind:'gather-wood',label:'采集木头',icon:'♧'},{kind:'gather-stone',label:'采集圆石',icon:'◇'},{kind:'protect',label:'保护主人',icon:'♜'}]
function accept(value:NumenSnapshot){if(disposed)return;state.value=value;if(autoScroll.value)void nextTick(()=>{if(logEl.value)logEl.value.scrollTop=logEl.value.scrollHeight})}
async function work(name:string,action:()=>Promise<unknown>){if(busy.value)return;busy.value=name;error.value='';try{await action()}catch(e){error.value=errText(e)}finally{busy.value=''}}
watch(()=>state.value.characterId,async(id)=>{boundCard.value=undefined;if(id){try{const card=await numenApi.cardGet(id);if(state.value.characterId===id)boundCard.value=card}catch(e){error.value=errText(e)}}})
async function refreshCards(){roleCards.value=await numenApi.cards();if(state.value.characterId)boundCard.value=await numenApi.cardGet(state.value.characterId)}
async function applyCharacter(id:string){await work('role',async()=>{accept(await numenApi.cardBind(id?{cardId:id}:null));toast(id?'角色卡已绑定，下次开始陪玩时生效':'已切换到通用人设','success');pageTab.value='runtime'})}
async function bind(){await work('bind',async()=>{
 const cloud=selected.value
 if(isCloudInstance(cloud)&&cloud.cloudSaveId){const ref={instanceId:cloud.cloudInstanceId,saveId:cloud.cloudSaveId};if(!await prepareCloud(ref))return;const result=await window.kamucl.invoke('numen:cloudBotsBind',ref) as {snapshot:NumenSnapshot};accept(result.snapshot);return}
 if(isCloudInstance(cloud)){error.value='请选择云端实例下的存档房间，机器人准入绑定到存档。';return}
 if(!localTarget.value){error.value='请选择本地实例';return}accept(await numenApi.bind(localTarget.value))
})}
async function saveModel(){await work('save',async()=>{saved.value=await numenApi.saveSettings({...form,...(form.apiKey?{apiKey:form.apiKey}:{apiKey:undefined})});form.apiKey='';toast('AI 接入配置已保存','success')})}
async function sendMessage(){const text=message.value.trim();if(!text)return;await work('send',async()=>{accept(await numenApi.send(text));message.value=''})}
async function chooseFiles(){if(isCloudInstance(selected.value)){await installCloudSupport();return}if(!canManageInstanceMods(resolveLauncherTarget(selected.value))){toast('安装 Numen 需要此实例的 MOD 管理权限，并且先绑定本地客户端','info');return}await work('files',async()=>{const instance=selected.value;if(!instance||!localTarget.value)throw new Error('请先选择已绑定本地客户端的实例');if(!['fabric','forge','neoforge'].includes(instance.loader??''))throw new Error('请先选择 Fabric、Forge 或 NeoForge 实例');files.value=await communityFiles('curseforge','1581109',{mcVersion:instance.mcVersion,loader:instance.loader,kind:'mod'});if(!files.value.length)throw new Error('该 Minecraft 版本与加载器暂时没有可下载的 Numen 文件');installOpen.value=true;planTarget.value={...localTarget.value};plan.value=undefined;pickedFile.value='';confirmWarnings.value=false;const file=files.value[0];pickedFile.value=file.fileId;plan.value=await prepareModInstall(planTarget.value!,{file})})}
async function chooseFile(file:CommunityFile){await work('plan',async()=>{if(plan.value)await discardModInstall(plan.value.id);plan.value=undefined;pickedFile.value=file.fileId;confirmWarnings.value=false;plan.value=await prepareModInstall(planTarget.value!,{file})})}
async function closeInstall(){if(busy.value)return;if(plan.value)await discardModInstall(plan.value.id);plan.value=undefined;installOpen.value=false}
async function install(){if(!plan.value)return;await work('install',async()=>{await commitModInstall(plan.value!.id,true);plan.value=undefined;installOpen.value=false;await refreshInstalled();if(localTarget.value)accept(await numenApi.bind(localTarget.value));accept(await window.kamucl.invoke('numen:instanceEnable',true) as NumenSnapshot);toast('Numen 已安装并启用；多人服务器需要发布对应服务端模组','success')})}
onMounted(async()=>{
  unsubscribe=numenApi.onState(accept)
  await work('load',async()=>{
    const [config,snapshot,cards]=await Promise.all([numenApi.settings(),numenApi.snapshot(),numenApi.cards()]);roleCards.value=cards;saved.value=config;Object.assign(form,config,{apiKey:''});accept(snapshot)
    if(snapshot.target){choice.value=options.value.find(option=>{const instance=option.instance;return isCloudInstance(instance)?instance.cloudLocalVersionId===snapshot.target!.id&&instance.cloudLocalFolder===snapshot.target!.folder:instance.id===snapshot.target!.id&&instance.folder===snapshot.target!.folder})?.key??''}
    if(!choice.value){const candidate=selectedLauncherInstance.value??options.value[0]?.instance;if(candidate)choice.value=JSON.stringify([candidate.folder,candidate.id]);if(localTarget.value)accept(await numenApi.bind(localTarget.value))}
    if(!state.value.installed)tab.value='companion';else if(!config.model)tab.value='model'
  })
})
onUnmounted(()=>{disposed=true;unsubscribe?.();if(plan.value)void discardModInstall(plan.value.id)})
</script>

<template>
  <section class="page ai-page">
    <header class="ai-heading">
      <div class="ai-title"><span class="ai-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="4" y="7" width="16" height="13" rx="4"/><path d="M12 3v4M2 12v4m20-4v4M9 16h6"/><circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/></svg></span><div><div class="eyebrow">NUMEN × KAMUCL NC</div><h1>AI 陪玩</h1><p>给同伴一个大脑，和你一起探索、建造与冒险。</p></div></div>
      <div class="ai-header-actions"><nav class="ai-view-switch" aria-label="AI 陪玩栏目"><button :class="{active:pageTab==='runtime'}" @click="pageTab='runtime'">陪玩控制台</button><button :class="{active:pageTab==='characters'}" @click="pageTab='characters'">角色卡库 <small>{{roleCards.length}}</small></button><button v-if="isCloudInstance(selected)" :class="{active:pageTab==='cloud'}" @click="pageTab='cloud'">准入与资源</button></nav><span class="runtime-state" :class="statusTone"><i></i>{{phaseLabels[state.phase]}}</span></div>
    </header>
    <div v-if="error" class="ai-alert" role="alert">{{error}}<button aria-label="关闭提示" @click="error=''">×</button></div>
    <div class="instance-bar">
      <label for="ai-instance">游戏实例</label><select id="ai-instance" v-model="choice" :disabled="!!busy||active" @change="bind"><option value="" disabled>选择一个游戏实例</option><option v-for="option in options" :key="option.key" :value="option.key">{{isCloudInstance(option.instance)?'云端':'本地'}} · {{displayVersionName(option.instance)}} · {{option.instance.mcVersion}} {{option.instance.loader||'原版'}}</option></select>
      <button class="btn btn-ghost btn-sm" :disabled="!!busy||!bound||(isCloudInstance(selected)&&!selected.cloudPermissions.includes('mods.manage'))" @click="enableInstance">{{state.enabled?'关闭实例陪玩':isCloudInstance(selected)?'安装并启用陪玩':'启用实例陪玩'}}</button><span v-if="state.target" class="mod-state" :class="{installed:state.installed}">{{state.installed?'Numen 已安装':'未安装 Numen'}}</span>
      <button class="btn btn-ghost btn-sm" :disabled="!!busy||active||!selected" @click="chooseFiles">{{isCloudInstance(selected)?'检查云端陪玩环境':state.installed?'检查模组版本':'一键安装上游 Numen'}}</button>
    </div>
    <CloudBotAccess v-if="pageTab==='cloud'&&isCloudInstance(selected)&&selected.cloudSaveId&&bound" :key="selected.id" :scope-key="selected.id" :can-review="selected.cloudPermissions.includes('bots.approve')" :can-review-models="selected.cloudPermissions.includes('models.approve')" :can-create-shared="selected.cloudPermissions.includes('bots.shared.create')" />
    <div v-else-if="pageTab==='cloud'" class="card config-body"><p>先选择云端存档，并准备对应客户端，再进入权限与审核。</p><button class="btn btn-primary" :disabled="!!busy" @click="bind">准备并绑定所选存档</button></div>
    <CharacterCards v-else-if="pageTab==='characters'" :current-id="state.characterId" :can-apply="!!state.selectedCompanion" :connected="state.connected" :companion-id="state.selectedCompanion" :companion-name="state.companions.find(c=>c.id===state.selectedCompanion)?.name" :running="active" :instance-target="localTarget" @changed="refreshCards" @apply="applyCharacter" />
    <div v-else-if="!bound||!state.installed" class="card numen-missing">
      <h2>{{bound?'此实例尚未安装 Numen':'先选择并检查实例'}}</h2><p>安装匹配 Minecraft 版本和加载器的上游 Numen Release 后，即可配置外部 AI 大脑。启动器通过 MCP 接入。</p>
      <button v-if="!bound" class="btn btn-primary" :disabled="!!busy||!selected" @click="bind">检查所选实例</button>
      <button v-else class="btn btn-primary" :disabled="!!busy||!selected" @click="chooseFiles">一键安装上游 Numen</button>
      <small v-if="isCloudInstance(selected)" class="help">云端安装需要 MOD 管理和实例修改权限；安装后会发布并同步客户端与服务端所需文件。</small>
    </div>
    <div v-else class="ai-workspace">
      <aside class="ai-config card">
        <div class="config-tabs" role="tablist"><button v-for="item in [{id:'companion',text:'同伴'},{id:'model',text:'AI 接入'},{id:'guide',text:'接入指南'}]" :key="item.id" role="tab" :aria-selected="tab===item.id" :class="{active:tab===item.id}" @click="tab=item.id as typeof tab">{{item.text}}</button></div>
        <div v-if="tab==='companion'" class="config-body">
          <h2>你的游戏同伴</h2><p class="muted">先启动游戏进入世界，再连接 Numen 的外接大脑。</p>
          <div class="connection-details"><span><small>MCP 端点</small><code>{{state.endpoint}}</code></span><span><small>外接大脑</small><b>{{state.mcpEnabled?'已开启':'未配置'}}</b></span><span><small>访问令牌</small><b>{{state.hasToken?'已从本机读取':'未生成'}}</b></span></div>
          <button class="btn btn-primary full" :disabled="!!busy||active||!localTarget||!bound" @click="work('connect',async()=>accept(await numenApi.connect()))">{{busy==='connect'?'正在连接…':state.connected?'重新连接游戏':'连接游戏'}}</button>
          <button v-if="!state.mcpEnabled||state.quietFallback" class="btn btn-ghost full" :disabled="!!busy||active||!state.installed||!bound" @click="work('enable',async()=>accept(await numenApi.enableMcp()))">配置本机外接大脑</button>
          <small v-if="!state.mcpEnabled||state.quietFallback" class="help">配置按钮仅在游戏关闭时修改文件；游戏正在运行时请在 Numen 设置里开启外接大脑，并关闭失联回退。</small>
          <div class="section-line"></div>
          <div class="section-title"><h2>选择同伴</h2><button class="text-button" :disabled="!!busy||!state.connected" @click="work('refresh',async()=>accept(await numenApi.refresh()))">刷新</button></div>
          <select aria-label="选择同伴" :value="state.selectedCompanion||''" :disabled="!!busy||!state.connected" @change="work('select',async()=>accept(await numenApi.select(($event.target as HTMLSelectElement).value)))"><option value="" disabled>{{state.companions.length?'选择一个同伴':'还没有同伴'}}</option><option v-for="companion in state.companions" :key="companion.id" :value="companion.id">{{companion.name}}{{ state.companionPhases?.[companion.id] ? ' · ' + phaseLabels[state.companionPhases[companion.id]] : '' }}</option></select>
          <div class="create-row"><input v-model="newName" aria-label="新同伴名字" placeholder="NomadBot" maxlength="16" :disabled="!!busy||!state.connected"><button class="btn btn-ghost btn-sm" :disabled="!!busy||!state.connected" @click="work('create',async()=>{accept(await numenApi.create(newName));toast('已发出召唤请求，请稍后刷新同伴列表','info')})">召唤</button></div>
          <small class="help">名字为 3–16 位英文字母、数字或下划线。</small>
          <div class="section-title"><h2>角色设定</h2><button class="text-button" @click="pageTab='characters'">管理角色卡 →</button></div>
          <select aria-label="同伴角色卡" :value="state.characterId||''" :disabled="!!busy||active||!state.selectedCompanion" @change="applyCharacter(($event.target as HTMLSelectElement).value)"><option value="">使用 AI 接入中的通用人设</option><option v-for="card in roleCards" :key="card.id" :value="card.id">{{card.name}}</option></select>
          <div v-if="boundCard" class="bound-role"><img v-if="boundCard.avatar" :src="boundCard.avatar" alt=""><div><strong>{{boundCard.name}}</strong><small>{{boundCard.text||'使用通用人设'}}</small></div></div>

          <small class="help">本地对话按同伴与角色卡分别保存。Numen 模组自身的札记仍归游戏中的同伴。</small>
          <div v-if="!isCloudInstance(selected)" class="local-body-controls"><button class="btn btn-ghost btn-sm" :disabled="!!busy||!bound" @click="work('local-adapter',async()=>{await invokeNumen('installLocalAdapter');toast('本地加入／退出适配已安装，重启游戏后生效','success')})">安装本地加入／退出适配</button><button class="btn btn-ghost" :disabled="!!busy||!state.connected||!state.selectedCompanion" @click="work('leave',async()=>accept(await invokeNumen('localBody','leave',state.selectedCompanion) as NumenSnapshot))">退出游戏 · 保留数据</button><label v-if="state.dormantCompanions?.length">已退出的机器人<select v-model="dormantChoice"><option value="" disabled>选择待恢复机器人</option><option v-for="bot in state.dormantCompanions" :key="bot.id" :value="bot.id">{{bot.name}}</option></select></label><button v-if="state.dormantCompanions?.length" class="btn btn-ghost" :disabled="!!busy||!state.connected||!dormantChoice" @click="work('join',async()=>accept(await invokeNumen('localBody','join',dormantChoice) as NumenSnapshot))">重新加入游戏</button></div><div class="brain-controls"><button class="btn btn-primary" :disabled="!!busy||active||!state.enabled||!state.connected||!bound||!state.selectedCompanion" @click="work('start',async()=>accept(await numenApi.start(state.selectedCompanion!)))">开始陪玩</button><button class="btn btn-stop" :disabled="!!busy||!state.connected" @click="work('stop',async()=>accept(await numenApi.stop()))">停止思考</button></div><small class="help">停止思考只关闭 AI 推理；机器人留在世界中，已开始的身体任务可能继续执行。</small><button class="btn btn-ghost" :disabled="!!busy||!state.connected||!state.selectedCompanion" @click="work('delete',async()=>accept(await numenApi.delete(state.selectedCompanion!)))">永久删除机器人…</button>
          <button class="text-button clear-history" :disabled="!!busy||active||!state.selectedCompanion" @click="work('history',async()=>accept(await numenApi.clearHistory()))">清空当前同伴的本地对话记录</button>
        </div>
        <form v-else-if="tab==='model'" class="config-body" @submit.prevent="saveModel">
          <h2>统一 AI 接入</h2><p class="muted">模型在本机调用，密钥不会上传到 NomadCraft。</p>
          <label>接口协议<select v-model="form.protocol" :disabled="active"><option value="openai">OpenAI 兼容 · Chat Completions</option><option value="anthropic">Anthropic · Messages</option></select></label>
          <label>API 地址<input v-model="form.baseUrl" type="url" :disabled="active" placeholder="https://your-provider.com/v1" autocomplete="off" spellcheck="false"></label>
          <label>API Key <span v-if="saved?.hasApiKey" class="saved-key">已保存</span><input v-model="form.apiKey" type="password" :disabled="active" :placeholder="saved?.hasApiKey?'留空保留已保存的密钥':'输入模型服务商提供的密钥'" autocomplete="new-password"></label>
          <small v-if="saved&&!saved.persistentSecrets" class="help">系统密钥保护不可用，输入的密钥仅在本次启动期间使用。</small>
          <label>模型名称<input v-model="form.model" :disabled="active" placeholder="填写服务商提供的 model ID" autocomplete="off" spellcheck="false"></label>
          <details class="ai-advanced"><summary>人设与运行参数</summary><label>同伴人设<textarea v-model="form.persona" :disabled="active" rows="3" maxlength="12000"></textarea></label>
          <div class="form-pair"><label>单次输出上限<input v-model.number="form.maxTokens" :disabled="active" type="number" min="256" max="32768" step="256"></label><label>单任务工具轮次<input v-model.number="form.maxTurns" :disabled="active" type="number" min="1" max="100"></label></div>
          </details>
          <div class="form-actions"><button type="submit" class="btn btn-primary" :disabled="!!busy||active">{{busy==='save'?'保存中…':'保存配置'}}</button><button type="button" class="btn btn-ghost" :disabled="!!busy||active||!saved?.model" @click="work('test',async()=>{await numenApi.testModel();toast('模型连接测试成功','success')})">{{busy==='test'?'测试中…':'测试已保存配置'}}</button></div>
          <small class="help">测试会发送一条简短请求；开始陪玩后使用这里保存的模型与人设。</small>
        </form>
        <div v-else class="config-body guide">
          <h2>三步开始陪玩</h2><ol><li><b>安装 Numen</b><p>选择对应 Minecraft 版本与加载器。多人游戏需要客户端和服务端都安装。</p></li><li><b>打开外接大脑</b><p>游戏内打开 Numen 面板，在设置中启用“外接大脑”，关闭“失联后内置大脑接管”。</p></li><li><b>配置 AI 并连接</b><p>保存模型 API 配置，进入世界，连接游戏、召唤或选择同伴，点击开始陪玩。</p></li></ol>
          <div class="guide-note"><b>由谁控制同伴？</b><p>开始后由启动器 Harness 接收游戏事件、调用模型并执行工具。Numen 的内置大脑停止推理，游戏内的身体本能和动作权限继续生效。</p></div>
          <p class="muted">不要让其他 MCP 客户端同时驱动同一位同伴。停止陪玩后外接模式仍保留；要恢复模组自带大脑，请在游戏设置中关闭外接大脑。</p>
          <small class="help">基于 minecraft-numen · LGPL-3.0。已有发布版与源码分支的接口可能不同，连接时会检查真实工具列表。</small>
        </div>
      </aside>
      <div class="ai-runtime">
        <section class="card command-card"><div class="section-title"><h2>快捷操作</h2><small class="muted">观察类直接执行 · 行动类交给 AI</small></div><div class="player-command-tools"><button class="btn btn-ghost btn-sm" :disabled="!!busy||!bound" @click="work('bridge',async()=>{await invokeNumen('installPlayerBridge');toast('玩家命令桥接已安装，下次启动游戏生效','success')})">安装玩家命令桥接</button><label>玩家快捷命令目标<select v-model="playerCommandBot" :disabled="!!busy" @focus="work('roster',refreshPlayerRoster)"><option value="" disabled>从在线机器人列表选择</option><option v-for="bot in onlinePlayerRoster" :key="bot.id" :value="bot.id">{{bot.name}}</option></select></label><div><button v-for="item in [{id:'permission',name:'查询权限模式'},{id:'settings',name:'打开游戏设置'},{id:'reset',name:'重置游戏内对话'},{id:'despawn',name:'永久遣散…'}]" :key="item.id" class="btn btn-ghost btn-sm" :disabled="!!busy||!playerCommandBot" @click="work('player-command',async()=>accept(await numenApi.playerCommand(item.id,playerCommandBot)))">{{item.name}}</button></div><label v-if="isCloudInstance(selected)">公有机器人游戏内任务<input v-model="message" maxlength="1800" placeholder="选择公有机器人后，按当前玩家身份发送" /></label><button v-if="isCloudInstance(selected)" class="btn btn-ghost btn-sm" :disabled="!!busy||!playerCommandBot||!message.trim()" @click="work('player-task',async()=>accept(await numenApi.playerCommand('task',playerCommandBot,message)))">按玩家身份发送任务</button><small class="help">以当前玩家身份发送，游戏权限生效；需要匹配加载器的 KAMUCL 桥接 MOD，支持 Fabric／Forge／NeoForge。下方是外部大脑任务，不是玩家聊天命令。</small></div>
<div class="quick-grid"><button v-for="command in commands" :key="command.kind" :disabled="!!busy||!state.connected||!state.selectedCompanion||(!command.direct&&!active)" @click="work(command.kind,async()=>accept(await numenApi.command(command.kind)))"><span>{{command.icon}}</span>{{command.label}}<small v-if="command.direct">直接</small></button></div></section>
